function detectCorners(source){if(!cvReady)return null;const scale=Math.min(1,850/Math.max(source.width,source.height));const c=canvas(source.width*scale,source.height*scale);c.getContext('2d').drawImage(source,0,0,c.width,c.height);const owned=[];const own=x=>(owned.push(x),x);try{const src=own(cv.matFromImageData(c.getContext('2d').getImageData(0,0,c.width,c.height))),gray=own(new cv.Mat()),blur=own(new cv.Mat()),edges=own(new cv.Mat()),contours=own(new cv.MatVector()),hierarchy=own(new cv.Mat()),kernel=own(cv.Mat.ones(5,5,cv.CV_8U));cv.cvtColor(src,gray,cv.COLOR_RGBA2GRAY);cv.GaussianBlur(gray,blur,new cv.Size(5,5),0);cv.Canny(blur,edges,45,140);cv.morphologyEx(edges,edges,cv.MORPH_CLOSE,kernel);cv.findContours(edges,contours,hierarchy,cv.RETR_LIST,cv.CHAIN_APPROX_SIMPLE);let best=null,bestScore=0;for(let i=0;i<contours.size();i++){const cnt=contours.get(i),approx=new cv.Mat();try{const area=cv.contourArea(cnt),fraction=area/(c.width*c.height);if(fraction<.12||fraction>.98)continue;cv.approxPolyDP(cnt,approx,.025*cv.arcLength(cnt,true),true);if(approx.rows!==4||!cv.isContourConvex(approx))continue;const p=[];for(let j=0;j<4;j++)p.push({x:approx.data32S[j*2],y:approx.data32S[j*2+1]});const sorted=orderCorners(p);let bad=false;for(let j=0;j<4;j++){const a=sorted[j],b=sorted[(j+1)%4],d=sorted[(j+3)%4];const cos=((b.x-a.x)*(d.x-a.x)+(b.y-a.y)*(d.y-a.y))/(Math.hypot(b.x-a.x,b.y-a.y)*Math.hypot(d.x-a.x,d.y-a.y));if(Math.abs(cos)>.88)bad=true}if(bad)continue;if(area>bestScore){bestScore=area;best=sorted.map(p=>({x:p.x/scale,y:p.y/scale}))}}finally{cnt.delete();approx.delete()}}return best}catch(e){console.warn('Detection unavailable',e);return null}finally{owned.reverse().forEach(x=>x.delete())}}
function renderOverlay(){const c=editing.source,s=$('overlay');s.setAttribute('viewBox',`0 0 ${c.width} ${c.height}`);s.innerHTML=`<polygon points="${editing.corners.map(p=>`${p.x},${p.y}`).join(' ')}"/>`+editing.corners.map((p,i)=>`<circle data-i="${i}" cx="${p.x}" cy="${p.y}" r="${Math.max(c.width,c.height)*.019}"/>`).join('')}
let drag=null;$('overlay').addEventListener('pointerdown',e=>{if(!editing)return;const i=e.target.dataset.i;if(i===undefined)return;drag=+i;$('overlay').setPointerCapture(e.pointerId);e.preventDefault()});$('overlay').addEventListener('pointermove',e=>{if(drag===null||!editing)return;const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform($('overlay').getScreenCTM().inverse());editing.corners[drag]={x:Math.max(0,Math.min(editing.source.width-1,pt.x)),y:Math.max(0,Math.min(editing.source.height-1,pt.y))};renderOverlay()});for(const evt of ['pointerup','pointercancel'])$('overlay').addEventListener(evt,()=>drag=null);
function openEditor(page,index=null){editing={source:page.source,corners:page.corners?structuredClone(page.corners):detectCorners(page.source)||fullCorners(page.source),index};$('filter').value=page.filter||'enhance';$('ratio').value=page.ratio||'auto';const c=$('edit-canvas');c.width=page.source.width;c.height=page.source.height;c.getContext('2d').drawImage(page.source,0,0);renderOverlay();$('detect-note').textContent=cvReady?'检查四角是否贴合纸张；可拖动圆点修正。':'自动找边尚未就绪，可拖动四角手动裁剪。';$('editor').showModal()}
async function nextFile(){if(!queue.length)return;const file=queue.shift();try{if(!file.type.startsWith('image/'))throw Error('请选择照片文件');const img=new Image();const url=URL.createObjectURL(file);try{img.src=url;await img.decode();const s=Math.min(1,3200/Math.max(img.naturalWidth,img.naturalHeight));const c=canvas(img.naturalWidth*s,img.naturalHeight*s);c.getContext('2d').drawImage(img,0,0,c.width,c.height);openEditor({source:c})}finally{URL.revokeObjectURL(url)}}catch(e){toast('无法读取照片，请使用 JPG、PNG 或 WebP 格式');nextFile()}}
function addFiles(files){if(pages.length+queue.length+files.length>40){toast('每份文档最多 40 页，请分批导出');return}queue.push(...files);if(!$('editor').open)nextFile()}
$('files').onchange=e=>{addFiles([...e.target.files]);e.target.value=''};$('capture').onchange=e=>{addFiles([...e.target.files]);e.target.value=''};$('import').onclick=()=>$('files').click();
$('cancel-edit').onclick=()=>$('editor').close();$('editor').addEventListener('close',()=>{editing=null;nextFile()});
$('detect').onclick=()=>{const p=detectCorners(editing.source);if(p){editing.corners=p;renderOverlay();$('detect-note').textContent='已找到纸张边缘，请检查并确认。'}else toast(cvReady?'未找到可靠边缘，请手动拖动四角':'引擎仍在加载，请稍后再试或手动裁剪')};$('full').onclick=()=>{editing.corners=fullCorners(editing.source);renderOverlay()};
function validQuad(p){let sign=0;for(let i=0;i<4;i++){const a=p[i],b=p[(i+1)%4],c=p[(i+2)%4];const v=(b.x-a.x)*(c.y-b.y)-(b.y-a.y)*(c.x-b.x);if(Math.abs(v)<1)return false;if(sign&&Math.sign(v)!==sign)return false;sign=Math.sign(v)}const area=Math.abs(p.reduce((s,a,i)=>{const b=p[(i+1)%4];return s+a.x*b.y-b.x*a.y},0))/2;return area>2500}
