$('save-edit').onclick=async()=>{if(!validQuad(editing.corners)){toast('四角不能交叉或过于接近，请沿纸张顺序调整');return}const btn=$('save-edit');btn.disabled=true;btn.textContent='正在矫正…';await new Promise(r=>setTimeout(r,40));try{const result=applyFilter(warp(editing.source,editing.corners,$('ratio').value),$('filter').value);const page={...editing,filter:$('filter').value,ratio:$('ratio').value,result,preview:result.toDataURL('image/jpeg',.75)};delete page.index;if(editing.index===null)pages.push(page);else pages[editing.index]=page;renderPages();$('editor').close();toast('已裁剪并矫正')}catch(e){toast(e.message||'裁剪失败，请调整四角重试')}finally{btn.disabled=false;btn.textContent='确认裁剪'}};
function renderPages(){const root=$('pages');root.replaceChildren();if(!pages.length)root.innerHTML='<div class="empty"><span>▤</span><p>你的扫描页会出现在这里</p><small>可以调整顺序、旋转和重新裁剪</small></div>';pages.forEach((p,i)=>{const el=document.createElement('article');el.className='page';el.innerHTML=`<div class="page-image"><img alt="第 ${i+1} 页扫描预览"></div><div class="page-meta"><span>第 ${i+1} 页</span><span>${p.result.width} × ${p.result.height}</span></div><div class="page-tools"><button data-action="left" aria-label="第 ${i+1} 页前移" ${i===0?'disabled':''}>←</button><button data-action="edit">裁剪</button><button data-action="optimize">优化</button><button data-action="rotate">旋转</button><button data-action="delete">删除</button><button data-action="right" aria-label="第 ${i+1} 页后移" ${i===pages.length-1?'disabled':''}>→</button></div>`;el.querySelector('img').src=p.preview;el.onclick=e=>{const action=e.target.dataset.action;if(action==='optimize')openOptimizer(p,i);else if(action==='edit')openEditor(p,i);else if(action==='delete'){pages.splice(i,1);renderPages()}else if(action==='left'||action==='right'){const j=i+(action==='left'?-1:1);if(j<0||j>=pages.length)return;[pages[i],pages[j]]=[pages[j],pages[i]];renderPages()}else if(action==='rotate'){const c=canvas(p.result.height,p.result.width),ctx=c.getContext('2d');ctx.translate(c.width,0);ctx.rotate(Math.PI/2);ctx.drawImage(p.result,0,0);p.turns=((p.turns||0)+1)%4;p.result=c;p.preview=c.toDataURL('image/jpeg',.75);renderPages()}};root.append(el)});$('count').textContent=`${pages.length} 页`;for(const id of ['download','share','clear'])$(id).disabled=!pages.length||working;$('export-note').textContent=pages.length?`${pages.length} 张扫描页将合成为一个 PDF`:'整理好页面后，生成一份多页 PDF'}
$('clear').onclick=()=>{if(confirm('清空本次所有扫描页？此操作无法撤销。')){pages.length=0;renderPages()}};
function safeName(){return ($('filename').value.trim()||'扫描文档').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_')+'.pdf'}
async function makePdf(){if(!window.jspdf)throw Error('PDF 组件未加载，请刷新页面后重试');let doc;const a4=$('size').value==='a4';for(let i=0;i<pages.length;i++){const c=pages[i].result,land=c.width>c.height;const dims=a4?(land?[297,210]:[210,297]):[c.width*.264583,c.height*.264583];if(!doc)doc=new jspdf.jsPDF({orientation:land?'landscape':'portrait',unit:'mm',format:dims,compress:true});else doc.addPage(dims,land?'landscape':'portrait');const pw=doc.internal.pageSize.getWidth(),ph=doc.internal.pageSize.getHeight(),margin=a4?8:0,s=Math.min((pw-margin*2)/c.width,(ph-margin*2)/c.height),w=c.width*s,h=c.height*s;doc.addImage(c.toDataURL('image/jpeg',+$('quality').value),'JPEG',(pw-w)/2,(ph-h)/2,w,h,undefined,'FAST');await new Promise(r=>setTimeout(r,0))}return doc.output('blob')}
let preparedFile=null;
function downloadFile(file){const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function fileSharingSupported(file){try{return !!navigator.share&&!!navigator.canShare?.({files:[file]})}catch{return false}}
function showShare(file){preparedFile=file;const supported=fileSharingSupported(file),wechat=/MicroMessenger/i.test(navigator.userAgent||'');$('share-ready-name').textContent=file.name+' · '+(file.size/1024/1024).toFixed(2)+' MB';$('send-file').hidden=!supported;$('share-help').textContent=wechat?'你正在微信内打开网页。建议使用右上角菜单，在 Safari 中打开，再生成 PDF 并分享。也可以尝试保存 PDF。':supported?'点击“打开系统分享”，在菜单中选择微信。若未显示微信，可查看“更多”，或先保存到“文件”后再分享。':'当前浏览器不支持直接分享 PDF。请保存文件，再从“文件”App 的分享菜单发送到微信。';$('share-ready').showModal()}
$('close-share').onclick=()=>$('share-ready').close();$('share-ready').addEventListener('close',()=>{preparedFile=null});
$('save-ready').onclick=()=>{if(preparedFile)downloadFile(preparedFile)};
$('send-file').onclick=()=>{if(!preparedFile)return;const btn=$('send-file');btn.disabled=true;try{const request=navigator.share({files:[preparedFile],title:preparedFile.name});Promise.resolve(request).catch(e=>{if(e.name!=='AbortError')$('share-help').textContent='未能打开文件分享。请点“保存 PDF”，再从“文件”App 发送到微信。'}).finally(()=>btn.disabled=false)}catch(e){btn.disabled=false;$('share-help').textContent='无法直接分享，请先保存 PDF，再从“文件”App 分享。'}};
async function exportPdf(share){if(!pages.length||working)return;working=true;renderPages();toast('正在生成 PDF…');try{const blob=await makePdf(),file=new File([blob],safeName(),{type:'application/pdf'});if(share)showShare(file);else{downloadFile(file);toast('PDF 已生成，请在下载或“文件”App 中查看')}}catch(e){toast(e.message||'导出失败，请重试')}finally{working=false;renderPages()}}
$('download').onclick=()=>exportPdf(false);$('share').onclick=()=>exportPdf(true);
function stopCamera(){clearInterval(liveTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;$('video').srcObject=null;$('live-overlay').innerHTML=''}$('live').addEventListener('close',stopCamera);$('close-camera').onclick=()=>$('live').close();
async function openLiveCamera(){if(pages.length>=40){toast('请先导出本次文档');return}if(!navigator.mediaDevices?.getUserMedia){$('capture').click();return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:2560},height:{ideal:1920}},audio:false});$('video').srcObject=stream;$('live').showModal();await $('video').play();liveTimer=setInterval(()=>{const v=$('video');if(!cvReady||!v.videoWidth)return;const c=canvas(640,640*v.videoHeight/v.videoWidth);c.getContext('2d').drawImage(v,0,0,c.width,c.height);const p=detectCorners(c),s=$('live-overlay');s.setAttribute('viewBox',`0 0 ${c.width} ${c.height}`);s.innerHTML=p?`<polygon points="${p.map(v=>`${v.x},${v.y}`).join(' ')}" fill="#79c88722" stroke="#90e2a0" stroke-width="3"/>`:'';$('camera-note').textContent=p?'已找到纸张，保持稳定后点击拍摄':'请将整张纸放入画面；拍摄后也可手动调角'},900)}catch(e){stopCamera();if($('live').open)$('live').close();toast('无法开启实时相机，改用手机拍照或相册');$('capture').click()}};
$('camera').onclick=()=>{if(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent||''))$('capture').click();else openLiveCamera()};$('live-camera').onclick=openLiveCamera;
$('shutter').onclick=()=>{const v=$('video');if(!v.videoWidth){toast('相机还在准备中');return}const scale=Math.min(1,3200/Math.max(v.videoWidth,v.videoHeight));const c=canvas(v.videoWidth*scale,v.videoHeight*scale);c.getContext('2d').drawImage(v,0,0,c.width,c.height);$('live').close();openEditor({source:c})};
for(const evt of ['dragenter','dragover'])$('dropzone').addEventListener(evt,e=>{e.preventDefault();$('dropzone').classList.add('over')});$('dropzone').addEventListener('dragleave',()=>$('dropzone').classList.remove('over'));$('dropzone').addEventListener('drop',e=>{e.preventDefault();$('dropzone').classList.remove('over');addFiles([...e.dataTransfer.files])});
window.addEventListener('pagehide',stopCamera);
const cvScript=document.createElement('script');cvScript.src='vendor/opencv.js';cvScript.async=true;cvScript.onerror=()=>{$('engine').textContent='自动裁边加载失败 · 可手动裁剪'};cvScript.onload=async()=>{try{if(window.cv?.Mat)ready();else if(window.cv?.then)window.cv.then(module=>{window.cv=module;ready()});else if(window.cv)window.cv.onRuntimeInitialized=ready}catch{$('engine').textContent='可使用手动裁剪'}};function ready(){cvReady=true;$('engine').textContent='● 自动裁边已就绪'}document.head.append(cvScript);setTimeout(()=>{if(!cvReady)$('engine').textContent='引擎仍在准备 · 可先手动裁剪'},20000);


